  const ultimo = Number.isFinite(e.ultimoMs) && e.ultimoMs > 0 ? e.ultimoMs : 0;
  if (ultimo && ahoraMs - ultimo > WL_OLVIDO_MS) return base;
  const nums = (v) => (Number.isFinite(v) && v > 0 ? v : 0);
  const charla = vdFichaCharla(e, ahoraMs);
