// La clave de la ficha es el teléfono de origen y solo dígitos: nunca un nombre que toque el prototipo.
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Las fichas de los teléfonos (`staticData.global.<CN_TENANT.claveFicha>`): la clave es un PARÁMETRO del tenant (la declara su librería en `CN_TENANT`), no un valor de este archivo.
// Una clave que no sea un nombre simple (o que toque el prototipo) no se usa: sin ficha, el nodo no escribe nada. Un nodo que SOLO LEE no escribe nada en los datos estáticos.
function cnClaveDeFichas() {
  const k = typeof CN_TENANT === 'object' && CN_TENANT ? CN_TENANT.claveFicha : '';
  return typeof k === 'string' && /^[a-z][A-Za-z0-9]{2,30}$/.test(k) && k !== 'constructor' && k !== 'prototype' ? k : '';
}
function cnMapaDeFichas(escribir) {
  const clave = cnClaveDeFichas();
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  if (!sd || !clave) return { sd: null, mapa: {} };
  const valido = Object.prototype.hasOwnProperty.call(sd, clave) && sd[clave] && typeof sd[clave] === 'object' && !Array.isArray(sd[clave]);
